import{z as d,x as c,o as s,c as p,q as l,j as i,D as o,d as r,s as n,S as E,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"内存屏障","description":"","frontmatter":{"title":"内存屏障","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-barrier-os.md","filePath":"cs/memory-barrier-os.md","lastUpdated":1791063341000}'),A={name:"cs/memory-barrier-os.md"};function B(m,e,C,u,f,h){const t=c("Mermaid");return s(),p("div",null,[e[2]||(e[2]=l('<h1 id="内存屏障" tabindex="-1">内存屏障 <a class="header-anchor" href="#内存屏障" aria-label="Permalink to &quot;内存屏障&quot;">​</a></h1><div class="epigraph"><p>临界区括号若只是源码里相邻的两行，编译器与 CPU 都可以把共享访存挪出括号；屏障把它钉回程序员以为的顺序。</p><footer>—— 据 Love, Linux Kernel Development；Lamport 顺序一致性与内核文档对 barrier 的整理</footer></div><p><a href="/cs/race-critical">上一课</a>要求共享不变量只在临界区里改，但还没说机器是否按源码序提交那些访存。<a href="/cs/memory-consistency">存储一致性</a> 在体系课给出 SC 与放宽模型。缺口是操作系统用法：<strong>内存屏障</strong>——防止编译器重排，并在弱序 CPU 上插入 fence，使「解锁前的写」被他核在「看到锁已释放」之前看见。本课不重导 TSO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无锁标志 <code>ready=1</code> 若排到 <code>data</code> 的写之前，读者看见 ready 仍可能读到旧 data。关中断不发射到别的核。缺口不是再定义竞争，而是承认：互斥锁的获取/释放必须带 <strong>acquire/release</strong> 语义，单独的 <code>LOAD</code>/<code>STORE</code> 要在文档化的点插 <code>smp_mb</code> 一类。内核把这写成显式屏障，而不是假设 SC。</p><p><span class="marginnote">直觉类比：把「写 data」与「立 ready 旗」想成寄包裹、发通知——若通知能比包裹先到（重排），收件人开箱就是空的。release 是「包裹全部付邮后才许发通知」，acquire 是「没收到通知不许拆箱」。</span></p><p><span class="marginnote">编译器屏障挡住代码运动；CPU fence 挡住 store/load 在总线上的可见序。两者都要，对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写者：更新数据，然后 <code>store-release</code> 标志。读者：<code>load-acquire</code> 标志，然后读数据。锁实现把 acquire 放在拿到锁之后、临界区之前，release 放在写完临界区之后、清锁字之前。本课不把每架构的指令助记符列完。</p><p><span class="marginnote">术语翻译：acquire/release 是一对「单向栅栏」——release 保证它之前的写不许被挪到它后面才生效，acquire 保证它之后的读不许提前到它之前。两者配对，才把「锁内的写」钉在「看见锁已释放」之前。</span></p>',10)),(s(),i(E,null,{default:o(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20REL%5B%22release%20%E6%A0%87%E5%BF%97%22%5D%0A%20%20ACQ%5B%22acquire%20%E8%AF%BB%E6%A0%87%E5%BF%97%22%5D%20--%3E%20R%5B%22%E8%AF%BB%E6%95%B0%E6%8D%AE%22%5D%0A%20%20REL%20--%3E%20ACQ%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[r("与"),a("a",{href:"/cs/percpu"},"per-CPU"),r(" 的关系：本核独享的槽若从未被他核读，可少加屏障；一旦跨核，纪律回来。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"屏障让临界区在多核上「看起来像原子」成为可实现的：他核要么看不见区内中间态，要么还看不见锁已释放。没有它，上一课的交错论证只对顺序一致纸机器成立。设备 DMA 与内存之间还有另一道，属 I/O 课；本课对象是 CPU 之间。",-1)),e[6]||(e[6]=a("p",null,"源码顺序到「他核看到的顺序」之间有两层重排，两种屏障各挡一层：",-1)),(s(),i(E,null,{default:o(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A0%81%E5%86%99%E7%9A%84%E9%A1%BA%E5%BA%8F%22%5D%20--%3E%20CMP%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E9%87%8D%E6%8E%92%EF%BC%9A%E6%8C%87%E4%BB%A4%E6%8C%AA%E4%BD%8D%22%5D%0A%20%20CMP%20--%3E%20BIN%5B%22%E7%94%9F%E6%88%90%E7%9A%84%E6%8C%87%E4%BB%A4%E5%BA%8F%22%5D%0A%20%20BIN%20--%3E%20CPU%5B%22CPU%20%E9%87%8D%E6%8E%92%EF%BC%9Astore%20%E7%BC%93%E5%86%B2%E4%B8%8E%E4%B9%B1%E5%BA%8F%22%5D%0A%20%20CPU%20--%3E%20SEEN%5B%22%E4%BB%96%E6%A0%B8%E5%AE%9E%E9%99%85%E7%9C%8B%E5%88%B0%E7%9A%84%E9%A1%BA%E5%BA%8F%22%5D%0A%20%20CBAR%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E5%B1%8F%E9%9A%9C%22%5D%20--%3E%20CMP%0A%20%20FENCE%5B%22CPU%20fence%22%5D%20--%3E%20CPU%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p>过度屏障会毁掉流水线；内核习惯用最弱足够的 acquire/release，而不是每处全序 fence。</p><p><span class="marginnote">常见误区：初学者「怕乱」就处处插全量 fence。屏障是流水线的刹车：每插一个，CPU 都要抽干缓冲、放弃重排。内核的纪律是取「最弱够用」的 acquire/release，只在真正跨核共享的点上付费。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 内存模型的全部 memory_order 枚举当 OS 正文，不写用户态如何探测乱序。也不把 RCU 的 synchronize 提前请进来。原子读改写指令本身既改数据又常自带屏障，下一课。</p><p>后课默认：跨核可见序要屏障或等价的锁语义。把「读改写」收成一条不可切的指令，下一课讲原子 RMW。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>临界区需要 acquire/release；源码相邻不等于可见序。</li><li>编译器屏障与 CPU fence 分工。</li><li>原子读改写是下一课。</li><li>出处：Love, <em>LKD</em>；体系课 <a href="/cs/memory-consistency">存储一致性</a>。</li></ul>',7))])}const _=d(A,[["render",B]]);export{P as __pageData,_ as default};
